72	// ============================================================================
73	// Custom pad value helpers for uint64_t-based PadValue enum
74	// ============================================================================
75	// PadValue uses uint64_t underlying type
76	// - Values 0-3 are standard enum cases (Null, Zero, Max, Min)
77	// - Custom values have bit 32 set, with the float bit pattern in bits [32:63]
78	
79	// Check if a PadValue is a custom value (bit 32+ set)
80	AICORE constexpr bool isCustomPadValue(PadValue pv)
81	{
82	    return static_cast<uint64_t>(pv) >= static_cast<uint64_t>(PadValue::CustomBase);
83	}
84	
85	// Extract the 32-bit value from a custom PadValue (returns the float bits)
86	AICORE constexpr uint32_t getCustomPadBits(PadValue pv)
87	{
88	    return static_cast<uint32_t>(static_cast<uint64_t>(pv) & 0xFFFFFFFFULL);
89	}
