91	// Helper to create a custom PadValue from a compile-time float/int constant
92	// Usage: PadCustom<-1.0f>, PadCustom<0.5f>, PadCustom<42>
93	namespace detail {
94	// Use union for compile-time float-to-bits (works on NPU compilers)
95	template <auto V>
96	constexpr uint32_t floatToBits()
97	{
98	    if constexpr (std::is_same_v<decltype(V), float>) {
99	        union {
100	            float f;
101	            uint32_t u;
102	        } conv = {V};
103	        return conv.u;
104	    } else if constexpr (std::is_same_v<decltype(V), double>) {
105	        union {
106	            float f;
107	            uint32_t u;
108	        } conv = {static_cast<float>(V)};
109	        return conv.u;
110	    } else if constexpr (std::is_integral_v<decltype(V)>) {
111	        return static_cast<uint32_t>(V);
112	    } else {
113	        return 0;
114	    }
115	}
116	} // namespace detail
117	
118	template <auto V>
119	inline constexpr PadValue PadCustom = static_cast<PadValue>(
120	    static_cast<uint64_t>(PadValue::CustomBase) | static_cast<uint64_t>(detail::floatToBits<V>()));
121	
122	// Helper constexpr function to create custom PadValue from float
123	// Works on both CPU_SIM and NPU (host + device) using __builtin_bit_cast
124	// Usage: constexpr PadValue PadCustomNeg1 = PadValueCustom(-1.0f);
125	// Note: For fp16/bf16, use PadValueCustomHalf()/PadValueCustomBf16() or pass fp16/bf16 bits directly
126	AICORE constexpr PadValue PadValueCustom(float value)
127	{
128	    return static_cast<PadValue>(
129	        static_cast<uint64_t>(PadValue::CustomBase) | static_cast<uint64_t>(__builtin_bit_cast(uint32_t, value)));
130	}
