540	        case MaskPattern::P0101:
541	            return PTO_TIME_2 * i * RowStride;
542	        case MaskPattern::P1010:
543	            return (PTO_TIME_2 * i + PTO_IDX_1) * RowStride;
544	        case MaskPattern::P0001:
545	            return PTO_TIME_4 * i * RowStride;
546	        case MaskPattern::P0010:
547	            return (PTO_TIME_4 * i + PTO_IDX_1) * RowStride;
548	        case MaskPattern::P0100:
549	            return (PTO_TIME_4 * i + PTO_IDX_2) * RowStride;
550	        case MaskPattern::P1000:
551	            return (PTO_TIME_4 * i + PTO_IDX_3) * RowStride;
552	        default:
