        src1.GetValidRow() == row && src1.GetValidCol() == col,
        "Fix: TADD input tile src1 valid shape mismatch with output tile dst shape.");
    TAdd_Impl<tile_shape>(dst.data(), src0.data(), src1.data(), row, col);
}
